// GET /api/ref?token=<main-or-worker-token> — Gardner master reference image.
// Private: same tokens as the dispatch API (query param). Lets a worker that
// cannot reach Storage by Iswar download the character reference from the
// dispatch host itself. B64 generated by scripts/gen-ref.py — do not hand-edit.
const IMG_B64 = '';
module.exports = async (req, res) => {
  const token = (req.query && req.query.token) || '';
  const mainTok = process.env.DISPATCH_MAIN_TOKEN || '';
  const workerToks = (process.env.DISPATCH_WORKER_TOKENS || '').split(',').map((s) => s.trim()).filter(Boolean);
  const ok = token && (token === mainTok || workerToks.includes(token));
  if (!ok) { res.status(401).json({ error: 'unauthorized' }); return; }
  const buf = Buffer.from(IMG_B64, 'base64');
  res.setHeader('Content-Type', 'image/webp');
  res.setHeader('Content-Length', String(buf.length));
  res.setHeader('Cache-Control', 'private, max-age=3600');
  res.status(200).send(buf);
};
